class Solution:
    def maxBen(self, k: int, benefit1: List[int], benefit2: List[int]) -> int:
        # Start with everything on A2, then move the k tasks where switching to A1 gains the most.
        gains = sorted((a - b for a, b in zip(benefit1, benefit2)), reverse=True)
        return sum(benefit2) + sum(gains[:k])

